INSERT INTO `ia_consultas` (`id`, `usuario_id`, `pregunta`, `titulo`, `sql_texto`, `grafico`, `favorito`, `veces`, `creado_en`, `ultimo_uso`) VALUES
	(1, 1, 'Top 10 productos más vendidos este mes', 'Top 10 productos más vendidos este mes', 'SELECT producto, SUM(cantidad) AS unidades_vendidas, ROUND(SUM(importe), 2) AS total_ventas FROM v_ia_detalle_ventas WHERE estado_venta = \'COMPLETADA\' AND fecha >= DATE_FORMAT(CURDATE(), \'%Y-%m-01\') GROUP BY producto ORDER BY unidades_vendidas DESC LIMIT 10', '{"tipo":"bar","x":"producto","y":"unidades_vendidas"}', 0, 1, '2026-10-01 07:10:40', '2026-10-01 07:10:40'),
	(2, 1, 'Top 10 productos más vendidos este mes', 'Top 10 productos más vendidos este mes', 'SELECT producto, SUM(cantidad) AS unidades_vendidas, ROUND(SUM(importe), 2) AS total_ventas FROM v_ia_detalle_ventas WHERE estado_venta = \'COMPLETADA\' AND fecha >= DATE_FORMAT(CURDATE(), \'%Y-%m-01\') GROUP BY producto ORDER BY unidades_vendidas DESC LIMIT 10', '{"tipo":"bar","x":"producto","y":"unidades_vendidas"}', 0, 1, '2026-10-01 08:00:16', '2026-10-01 08:00:16'),
	(3, 1, 'Productos con stock bajo', 'Productos con Stock Bajo', 'SELECT producto, categoria, sucursal, stock, stock_minimo FROM v_ia_stock_sucursal WHERE stock <= stock_minimo ORDER BY (stock - stock_minimo) ASC LIMIT 50', '{"tipo":"bar","x":"producto","y":"stock"}', 0, 1, '2026-10-01 08:01:06', '2026-10-01 08:01:06'),
	(4, 1, 'Ventas por día de los últimos 30 días', 'Ventas por día de los últimos 30 días', 'SELECT dia, ROUND(SUM(total - devuelto), 2) AS total_ventas FROM v_ia_ventas WHERE estado = \'COMPLETADA\' AND dia >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) GROUP BY dia ORDER BY dia ASC', '{"tipo":"line","x":"dia","y":"total_ventas"}', 0, 1, '2026-10-01 08:32:17', '2026-10-01 08:32:17'),
	(5, 1, 'listado de los productos que se estan quedando sin stock', 'Productos con stock bajo', 'SELECT s.producto, s.categoria, p.marca, s.stock, s.stock_minimo, s.sucursal FROM v_ia_stock_sucursal s LEFT JOIN v_ia_productos p ON s.producto_id = p.producto_id WHERE s.stock <= s.stock_minimo ORDER BY s.stock ASC LIMIT 50', '{"tipo":"none","x":"","y":""}', 0, 1, '2026-10-01 08:59:29', '2026-10-01 08:59:29'),
	(6, 1, 'reporte general de la semana de todas la ventas por sucursales', 'Ventas por Sucursal de la Semana', 'SELECT sucursal, COUNT(venta_id) AS numero_ventas, ROUND(SUM(total - devuelto), 2) AS total_ventas FROM v_ia_ventas WHERE estado = \'COMPLETADA\' AND fecha >= DATE_SUB(\'2026-10-01\', INTERVAL WEEKDAY(\'2026-10-01\') DAY) GROUP BY sucursal ORDER BY total_ventas DESC', '{"tipo":"bar","x":"sucursal","y":"total_ventas"}', 0, 1, '2026-10-01 09:25:38', '2026-10-01 09:25:38'),
	(7, 1, 'muestra los detalles de la venta de los 3 ultimos días', 'Detalle de ventas de los últimos 3 días', 'SELECT v.fecha, v.sucursal, v.cajero, v.cliente, v.tipo_comprobante, v.comprobante, d.producto, d.cantidad, d.precio_unitario, ROUND(d.importe, 2) AS importe, ROUND(d.utilidad, 2) AS utilidad FROM v_ia_ventas v INNER JOIN v_ia_detalle_ventas d ON v.venta_id = d.venta_id WHERE v.estado = \'COMPLETADA\' AND d.estado_venta = \'COMPLETADA\' AND v.fecha >= \'2026-09-28 00:00:00\' ORDER BY v.fecha DESC LIMIT 100', '{"tipo":"none","x":"","y":""}', 0, 1, '2026-10-01 09:26:16', '2026-10-01 09:26:16'),
	(8, 1, 'Top 10 productos más vendidos este mes', 'Top 10 productos más vendidos este mes', 'SELECT producto, SUM(cantidad) AS unidades_vendidas, ROUND(SUM(importe), 2) AS total_ventas FROM v_ia_detalle_ventas WHERE estado_venta = \'COMPLETADA\' AND fecha >= DATE_FORMAT(CURDATE(), \'%Y-%m-01\') GROUP BY producto ORDER BY unidades_vendidas DESC LIMIT 10', '{"tipo":"bar","x":"producto","y":"unidades_vendidas"}', 0, 1, '2026-10-01 10:29:33', '2026-10-01 10:29:33'),
	(9, 1, 'productos disponibles', 'Productos Disponibles en Stock', 'SELECT producto, categoria, marca, stock, unidad, ROUND(precio_venta, 2) AS precio_venta FROM v_ia_productos WHERE activo = 1 AND stock > 0 ORDER BY stock DESC LIMIT 50', '{"tipo":"none","x":"producto","y":"stock"}', 0, 1, '2026-10-01 11:30:59', '2026-10-01 11:30:59'),
	(10, 1, 'sacame un detalle de los productos que se estan por quedar sin stock', 'Productos con Stock Bajo', 'SELECT producto, categoria, stock, stock_minimo, sucursal FROM v_ia_stock_sucursal WHERE stock <= stock_minimo ORDER BY stock ASC LIMIT 50', '{"tipo":"bar","x":"producto","y":"stock"}', 0, 1, '2026-10-01 11:44:52', '2026-10-01 11:44:52'),
	(11, 1, 'comparativo de las ventas de los dos ultimos meses', 'Comparativo de ventas de los últimos dos meses', 'SELECT DATE_FORMAT(fecha, \'%Y-%m\') AS mes, COUNT(venta_id) AS total_ventas, ROUND(SUM(total - devuelto), 2) AS monto_neto FROM v_ia_ventas WHERE estado = \'COMPLETADA\' AND fecha >= DATE_SUB(DATE_FORMAT(CURDATE(), \'%Y-%m-01\'), INTERVAL 1 MONTH) AND fecha < DATE_FORMAT(CURDATE(), \'%Y-%m-01\') GROUP BY DATE_FORMAT(fecha, \'%Y-%m\') ORDER BY mes ASC', '{"tipo":"bar","x":"mes","y":"monto_neto"}', 0, 1, '2026-10-01 11:45:48', '2026-10-01 11:45:48'),
	(12, 1, 'comparativo de las ventas de las dos ultimas semanas', 'Comparativo de ventas de las dos últimas semanas', 'SELECT CASE WHEN fecha >= DATE_SUB(CURDATE(), INTERVAL 7 DAY) THEN \'Última semana\' ELSE \'Semana anterior\' END AS periodo, COUNT(venta_id) AS total_ventas, ROUND(SUM(total - devuelto), 2) AS monto_neto FROM v_ia_ventas WHERE estado = \'COMPLETADA\' AND fecha >= DATE_SUB(CURDATE(), INTERVAL 14 DAY) GROUP BY CASE WHEN fecha >= DATE_SUB(CURDATE(), INTERVAL 7 DAY) THEN \'Última semana\' ELSE \'Semana anterior\' END ORDER BY MIN(fecha) ASC', '{"tipo":"bar","x":"periodo","y":"monto_neto"}', 0, 1, '2026-10-01 11:46:16', '2026-10-01 11:46:16'),
	(13, 1, 'productos que no han tenido movimiento de ventas', 'Productos sin movimientos de ventas', 'SELECT producto_id, codigo, producto, categoria, marca, stock FROM v_ia_productos WHERE activo = 1 AND producto_id NOT IN (SELECT DISTINCT producto_id FROM v_ia_detalle_ventas WHERE estado_venta = \'COMPLETADA\') ORDER BY stock DESC LIMIT 50', '{"tipo":"none","x":"","y":""}', 0, 1, '2026-10-01 13:39:42', '2026-10-01 13:39:42'),
	(14, 1, 'productos disponibles para la venta', 'Productos Disponibles para la Venta', 'SELECT producto_id, codigo, producto, categoria, marca, stock, unidad, precio_venta FROM v_ia_productos WHERE activo = 1 AND stock > 0 ORDER BY stock DESC LIMIT 100', '{"tipo":"none","x":"","y":""}', 0, 1, '2026-10-01 13:40:01', '2026-10-01 13:40:01'),
	(15, 1, 'ventas de las dos ultimas semana y haz un comparativo entre ellas', 'Comparativo de ventas: últimas dos semanas', 'SELECT CASE WHEN fecha >= DATE_SUB(CURDATE(), INTERVAL 7 DAY) THEN \'Semana Actual\' ELSE \'Semana Anterior\' END AS semana, COUNT(DISTINCT venta_id) AS total_ventas, ROUND(SUM(total - devuelto), 2) AS monto_total FROM v_ia_ventas WHERE estado = \'COMPLETADA\' AND fecha >= DATE_SUB(CURDATE(), INTERVAL 14 DAY) GROUP BY semana ORDER BY semana DESC', '{"tipo":"bar","x":"semana","y":"monto_total"}', 0, 1, '2026-10-01 13:45:15', '2026-10-01 13:45:15'),
	(16, 1, 'Top 10 productos más vendidos este mes', 'Top 10 productos más vendidos este mes', 'SELECT producto, SUM(cantidad) AS unidades_vendidas, ROUND(SUM(importe), 2) AS total_ventas FROM v_ia_detalle_ventas WHERE estado_venta = \'COMPLETADA\' AND fecha >= DATE_FORMAT(CURDATE(), \'%Y-%m-01\') GROUP BY producto ORDER BY unidades_vendidas DESC LIMIT 10', '{"tipo":"bar","x":"producto","y":"unidades_vendidas"}', 0, 1, '2026-10-02 00:21:25', '2026-10-02 00:21:25'),
	(17, 1, 'Top 10 productos más vendidos este mes', 'Top 10 productos más vendidos este mes', 'SELECT producto, SUM(cantidad) AS unidades_vendidas, ROUND(SUM(importe), 2) AS total_ventas FROM v_ia_detalle_ventas WHERE estado_venta = \'COMPLETADA\' AND fecha >= DATE_FORMAT(CURDATE(), \'%Y-%m-01\') GROUP BY producto ORDER BY unidades_vendidas DESC LIMIT 10', '{"tipo":"bar","x":"producto","y":"unidades_vendidas"}', 0, 1, '2026-10-02 00:24:02', '2026-10-02 00:24:02'),
	(18, 1, 'productos disponibles para la venta', 'Productos Disponibles para la Venta', 'SELECT producto, categoria, marca, stock, unidad, precio_venta FROM v_ia_productos WHERE activo = 1 AND stock > 0 ORDER BY producto ASC LIMIT 100', '{"tipo":"none","x":"","y":""}', 0, 1, '2026-10-04 11:18:14', '2026-10-04 11:18:14'),
	(19, 1, 'indicma los productos disponibles para la venta de hoy', 'Productos Disponibles para la Venta', 'SELECT t1.producto, t1.categoria, t2.marca, t1.stock, t1.sucursal FROM v_ia_stock_sucursal t1 JOIN v_ia_productos t2 ON t1.producto_id = t2.producto_id WHERE t1.stock > 0 AND t2.activo = 1 ORDER BY t1.producto LIMIT 100', '{"tipo":"none","x":"","y":""}', 0, 1, '2026-10-04 12:40:20', '2026-10-04 12:40:20'),
	(20, 1, 'indicame que productos se estan quedando sin stock', 'Productos con stock bajo', 'SELECT producto, categoria, marca, stock, stock_minimo FROM v_ia_productos WHERE stock_bajo = 1 AND activo = 1 ORDER BY stock ASC LIMIT 50', '{"tipo":"bar","x":"producto","y":"stock"}', 0, 1, '2026-10-04 12:41:19', '2026-10-04 12:41:19'),
	(21, 1, 'dame un listado de los productos disponibles para la venta de hoy', 'Productos disponibles', 'SELECT producto, categoria, marca, stock, precio_venta FROM v_ia_productos WHERE activo = 1 AND stock > 0 ORDER BY producto ASC', '{"tipo":"none","x":"","y":""}', 0, 1, '2026-10-04 22:20:22', '2026-10-04 22:20:22'),
	(22, 1, 'dame un listado de los clientes y el total de compra que han realizado hasta la fecha', 'Clientes y Total Comprado', 'SELECT nombre AS cliente, num_compras, total_comprado, saldo_deuda FROM v_ia_clientes WHERE activo = 1 ORDER BY total_comprado DESC LIMIT 50', '{"tipo":"bar","x":"cliente","y":"total_comprado"}', 0, 1, '2026-10-04 22:21:40', '2026-10-04 22:21:40'),
	(23, 1, 'dame un listado de los productos que se estan quedando sin stock', 'Productos con stock bajo', 'SELECT producto, categoria, stock, stock_minimo, sucursal FROM v_ia_stock_sucursal WHERE stock <= stock_minimo ORDER BY stock ASC LIMIT 50', '{"tipo":"none","x":"","y":""}', 0, 1, '2026-10-04 22:22:29', '2026-10-04 22:22:29');
